import type { CaseRecord, Source } from "./types";

const lastVerified = "2026-08-28";
const official = (id: string, title: string, url: string, publisher = "Supreme Court of Canada"): Source => ({
  id,
  title,
  publisher,
  url,
  type: "Primary",
  category: "Judgment",
  verificationStatus: "Verified",
  supports: ["Citation", "Decision date", "Court", "Disposition", "Reasons for judgment"],
  accessedDate: lastVerified,
});

const encyclopedia = (id: string, title: string, url: string): Source => ({
  id,
  title,
  publisher: "The Canadian Encyclopedia",
  url,
  type: "Secondary",
  category: "Background Explainer",
  verificationStatus: "Secondary Source",
  supports: ["Historical background", "Plain-language context"],
  note: "Background only. The official judgment remains authoritative.",
  accessedDate: lastVerified,
});

const shared = {
  court: "Supreme Court of Canada",
  courtLevel: "Supreme Court",
  status: "Decided" as const,
  verificationLevel: "Verified" as const,
  contentStatus: "Published" as const,
  landmark: false,
  lastVerified,
  createdAt: "2026-08-26",
  updatedAt: "2026-08-26",
  judges: ["See official judgment"],
  importantQuotes: [],
  filingDate: undefined,
  coordinates: undefined,
};

type AdditionalCaseSeed = {
  slug: string;
  caseName: string;
  citation: string;
  decisionDate: string;
  provinceTerritory: string;
  outcome: CaseRecord["outcome"];
  significance: number;
  summary: string;
  decision: string;
  importance: string;
  legalTopics: string[];
  treaties?: string[];
  communities: string[];
  indigenousGroup?: CaseRecord["indigenousGroup"];
  parties: string[];
  officialUrl: string;
  relatedCases?: CaseRecord["relatedCases"];
  region?: string;
  court?: string;
  courtLevel?: string;
  courtFileNumber?: string;
  publisher?: string;
  judges?: string[];
  verifiedDate?: string;
};

const additionalCase = (seed: AdditionalCaseSeed): CaseRecord => ({
  ...shared,
  id: `case-${seed.slug}`,
  slug: seed.slug,
  caseName: seed.caseName,
  officialCitation: seed.citation,
  neutralCitation: /^\d{4} [A-Z][A-Z0-9.-]* \d+$/.test(seed.citation) ? seed.citation : undefined,
  court: seed.court ?? shared.court,
  courtLevel: seed.courtLevel ?? shared.courtLevel,
  courtFileNumber: seed.courtFileNumber,
  provinceTerritory: seed.provinceTerritory,
  decisionDate: seed.decisionDate,
  outcome: seed.outcome,
  significance: seed.significance,
  landmark: seed.significance >= 9,
  summaryShort: seed.summary,
  summaryFull: seed.summary,
  facts: seed.summary,
  indigenousArgument: "The Indigenous parties asked the Court to recognize or enforce the rights, obligations, jurisdiction, or remedies described in the official judgment.",
  otherPartyArgument: "The opposing parties advanced the position recorded in the official judgment. Consult the reasons for the complete submissions and procedural history.",
  decision: seed.decision,
  importance: seed.importance,
  beforeCase: "The governing doctrine or its application remained contested before this decision.",
  afterCase: seed.importance,
  legalTopics: seed.legalTopics,
  treaties: seed.treaties ?? [],
  indigenousCommunities: seed.communities,
  indigenousGroup: seed.indigenousGroup ?? "First Nations",
  parties: seed.parties,
  sources: [official(`src-${seed.slug}-official`, seed.caseName, seed.officialUrl, seed.publisher)],
  relatedCases: seed.relatedCases ?? [],
  timelineEvents: [{ date: seed.decisionDate, court: seed.court ?? shared.court, citation: seed.citation, outcome: seed.decision, sourceUrl: seed.officialUrl }],
  approximateRegion: seed.region ?? seed.provinceTerritory,
  judges: seed.judges ?? shared.judges,
  lastVerified: seed.verifiedDate ?? shared.lastVerified,
  createdAt: seed.verifiedDate ?? shared.createdAt,
  updatedAt: seed.verifiedDate ?? shared.updatedAt,
});

